'use strict';
const TaskNotifier={timer:null,busy:false,stopped:false,previous:null,pending:new Map(),latest:new Map(),initial:true,
 key(t){return [t.kind,t.id,t.status].join(':');},
 start(){window.Sound467?.init();this.storageKey='musonoi-tasks:'+CurrentUser.id+':'+ProductContext.code+':'+(sessionStorage.getItem('musonoi-login-notice')||'restored-session');try{const saved=JSON.parse(sessionStorage.getItem(this.storageKey));if(Array.isArray(saved)){this.previous=new Set(saved);this.initial=false;}}catch{}window.addEventListener('session-expired',()=>this.stop());window.addEventListener('inventory-changed',()=>this.schedule(300));window.addEventListener('focus',()=>this.schedule(0));document.addEventListener('visibilitychange',()=>{if(!document.hidden)this.schedule(0);});this.poll();},
 stop(){window.Sound467?.stop();this.stopped=true;clearTimeout(this.timer);clearTimeout(this.openTimer);document.getElementById('task-notice')?.remove();this.pending.clear();window.UnifiedNavigation?.setTasks([]);$('task-notice-entry')?.remove();},
 schedule(ms){if(this.stopped)return;clearTimeout(this.timer);this.timer=setTimeout(()=>this.poll(),ms);},
 async poll(){if(this.stopped||!window.AppSignedIn)return;if(this.busy){this.schedule(1000);return;}if(document.hidden){this.schedule(15000);return;}this.busy=true;try{const data=ProductContext.isCopper()?await API.request('/v34/todos'):{items:(await API.request('/cobalt/ui461/tasks')).pending};if(this.stopped)return;window.UnifiedNavigation?.setTasks(data.items);this.latest=new Map(data.items.map(t=>[this.key(t),t]));const keys=new Set(this.latest.keys()),added=[...keys].filter(k=>!this.previous?.has(k));for(const k of [...this.pending.keys()]){if(!keys.has(k))this.pending.delete(k);else this.pending.set(k,this.latest.get(k));}for(const k of added)this.pending.set(k,this.latest.get(k));window.Sound467?.notify(added,{initial:this.previous===null});if(!this.pending.size&&$('task-notice')){$('task-notice').close();$('task-notice').remove();this.initial=false;}this.previous=keys;if(!keys.size)this.initial=false;if(!this.pending.size)sessionStorage.setItem(this.storageKey,JSON.stringify([...keys]));this.badge(data.items.length);this.open();}catch(e){if(e.statusCode===401)this.stop();}finally{this.busy=false;this.schedule(15000);}},
 badge(count){let link=$('task-notice-entry');if(!link){link=document.createElement('a');link.id='task-notice-entry';link.className='task-notice-entry';link.href='/overview?management=todos';document.querySelector('.top-actions').append(link);}link.innerHTML='<span>我的待办</span><strong data-no-i18n>'+count+'</strong>';link.classList.toggle('has-tasks',count>0);link.setAttribute('aria-live','polite');I18n.apply();},
 open(){if(this.stopped||!this.pending.size)return;const opened=$('task-notice');if(opened){this.draw(opened);return;}if(document.querySelector('dialog[open]')){clearTimeout(this.openTimer);this.openTimer=setTimeout(()=>this.open(),800);return;}const box=document.createElement('dialog');box.id='task-notice';box.className='task-notice';box.setAttribute('aria-labelledby','task-notice-title');box.innerHTML='<div class="task-notice-icon" aria-hidden="true">!</div><h2 id="task-notice-title"></h2><p class="task-notice-description"></p><div class="task-notice-list"></div><div class="task-notice-actions"><button type="button" class="button secondary" data-task-dismiss>稍后处理</button><a class="button primary" href="/overview?management=todos" data-task-all>查看全部待办</a></div>';const trigger=document.activeElement;document.body.append(box);const close=()=>{box.close();box.remove();this.pending.clear();this.initial=false;if(trigger?.isConnected)trigger.focus({preventScroll:true});};box.querySelector('[data-task-dismiss]').onclick=close;box.querySelector('[data-task-all]').onclick=close;box.oncancel=e=>{e.preventDefault();close();};box.addEventListener('click',e=>{if(e.target.closest('[data-task-link]'))close();});this.draw(box);box.showModal();box.querySelector('[data-task-dismiss]').focus();},
 draw(box){for(const k of [...this.pending.keys()])if(!this.latest.has(k))this.pending.delete(k);if(!this.pending.size){box.close();box.remove();return;}box.querySelector('h2').textContent=this.initial?'登录待办提醒':'您有新的待办单据';box.querySelector('.task-notice-description').innerHTML='<span>'+(this.initial?'以下为您当前需要办理或审批的全部单据':'以下单据需要您办理或审批')+'</span> · <strong data-no-i18n>'+this.pending.size+'</strong> <span>项</span>';box.querySelector('.task-notice-list').innerHTML=[...this.pending.values()].map(t=>'<a data-task-link class="task-notice-item" href="'+esc(t.href)+'"><span>'+esc(ManagementLabels.names[t.kind]||t.kind)+'</span><strong data-no-i18n>'+esc(t.document_no)+'</strong><span aria-hidden="true">→</span></a>').join('');sessionStorage.setItem(this.storageKey,JSON.stringify([...this.latest.keys()]));I18n.apply();}
};
TaskNotifier.start();
